Code.Terraform:
```hcl
resource "aws_bedrockagentcore_agent_runtime" "example" {
  agent_runtime_name = "<example_resource_name>"
  role_arn           = "<example_resource_id>"

  agent_runtime_artifact {
    container_configuration {
      container_uri = "<example_resource_id>"
    }
  }

  # Critical: VPC mode with subnets and security groups makes the check PASS
  network_configuration {
    network_mode = "VPC"
    network_mode_config {
      subnets         = ["<example_resource_id>"]
      security_groups = ["<example_resource_id>"]
    }
  }
}
```
